CREATE TABLE "turnos_trabajo" ("id" TEXT NOT NULL PRIMARY KEY,"empresaId" TEXT NOT NULL DEFAULT '1',"codigo" TEXT NOT NULL,"nombre" TEXT NOT NULL,"inicioMinuto" INTEGER NOT NULL,"finMinuto" INTEGER NOT NULL,"refrigerioMinuto" INTEGER NOT NULL DEFAULT 60,"toleranciaMinuto" INTEGER NOT NULL DEFAULT 0,"activo" BOOLEAN NOT NULL DEFAULT true,"creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "turnos_trabajo_empresaId_codigo_key" ON "turnos_trabajo"("empresaId","codigo");
ALTER TABLE "empleados" ADD COLUMN "turnoTrabajoId" TEXT REFERENCES "turnos_trabajo"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "registros_asistencia" ("id" TEXT NOT NULL PRIMARY KEY,"empresaId" TEXT NOT NULL DEFAULT '1',"empleadoId" TEXT NOT NULL,"fecha" DATETIME NOT NULL,"entrada" DATETIME,"salida" DATETIME,"minutosTrabajados" INTEGER NOT NULL DEFAULT 0,"minutosTardanza" INTEGER NOT NULL DEFAULT 0,"minutosSobretiempo" INTEGER NOT NULL DEFAULT 0,"ausenciaJustificada" BOOLEAN NOT NULL DEFAULT false,"observacion" TEXT,"estado" TEXT NOT NULL DEFAULT 'BORRADOR',"usuarioId" TEXT NOT NULL,"usuarioNombre" TEXT NOT NULL,"aprobadoEn" DATETIME,"aprobadoPorId" TEXT,"aprobadoPorNombre" TEXT,"creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "registros_asistencia_empleadoId_fkey" FOREIGN KEY ("empleadoId") REFERENCES "empleados"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "registros_asistencia_empleadoId_fecha_key" ON "registros_asistencia"("empleadoId","fecha");
CREATE INDEX "registros_asistencia_empresaId_fecha_estado_idx" ON "registros_asistencia"("empresaId","fecha","estado");
